int ho_linguistics_adjust_array_out
              (double *array_out,uchar word_end,uchar word_start,int last_char_i)

{
  if (word_end == '\0') {
    array_out[0xc] = array_out[0xc] - 0.3;
    array_out[0xf] = array_out[0xf] - 0.3;
    array_out[0x11] = array_out[0x11] - 0.3;
    array_out[0x15] = array_out[0x15] - 0.3;
    array_out[0x1c] = array_out[0x1c] - 0.3;
    array_out[0x1d] = array_out[0x1d] - 0.3;
    array_out[0x20] = array_out[0x20] - 0.3;
    array_out[0x17] = (array_out[0x17] - 0.3) - 0.3;
    array_out[0x22] = array_out[0x22] - 0.3;
    array_out[0x23] = array_out[0x23] - 0.3;
  }
  else {
    array_out[0xb] = array_out[0xb] - 0.3;
    array_out[0xe] = array_out[0xe] - 0.3;
    array_out[0x10] = array_out[0x10] - 0.3;
    array_out[0x14] = array_out[0x14] - 0.3;
    array_out[0x16] = array_out[0x16] - 0.3;
  }
  return 0;
}
